1	package tariff
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// VersionsInRange 场景的固定时间线（UTC，结束时刻均不含）：
12	//
13	//	旧版 seat-v1：单价 150 分，2026-03-01 00:00 起生效，登记结束 2026-03-31 00:00
14	//	新版 seat-v2：单价 180 分，2026-03-10 00:00 起替代旧版，2026-03-20 00:00 结束
15	//
16	// 查询时旧版的实际有效区间已被截断到 3 月 10 日。
17	var (
18		rngV1Start = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
19		rngV1End   = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
20		rngV2Start = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
21		rngV2End   = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)
22	)
23	
24	func newRangeBook(t *testing.T) *Book {
25		t.Helper()
26		b := NewBook()
27		v1End := rngV1End
28		if err := b.RegisterVersion(RegisterRequest{
29			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
30			Start: rngV1Start, End: &v1End,
31		}); err != nil {
32			t.Fatalf("register seat-v1: %v", err)
33		}
34		v2End := rngV2End
35		if err := b.RegisterVersion(RegisterRequest{
36			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
37			Start: rngV2Start, End: &v2End, Replaces: "seat-v1",
38		}); err != nil {
39			t.Fatalf("register seat-v2: %v", err)
40		}
41		return b
42	}
43	
44	func rangeIDs(views []VersionView) []string {
45		ids := make([]string, len(views))
46		for i, v := range views {
47			ids[i] = v.VersionID
48		}
49		return ids
50	}
51	
52	func equalIDs(got []string, want ...string) bool {
53		if len(got) != len(want) {
54			return false
55		}
56		for i := range want {
57			if got[i] != want[i] {
58				return false
59			}
60		}
61		return true
62	}
63	
64	// 题目示例：查看 3 月 9 日至 3 月 11 日应得到旧版和新版；
65	// 查看 3 月 10 日至 3 月 25 日只得到新版；查看 3 月 20 日至 3 月 25 日为空。
66	func TestVersionsInRangeSpecExample(t *testing.T) {
67		b := newRangeBook(t)
68	
69		got, err := b.VersionsInRange("seat",
70			time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
71			time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
72		if err != nil {
73			t.Fatalf("3 月 9 日至 11 日不应报错: %v", err)
74		}
75		if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
76			t.Fatalf("3 月 9 日至 11 日应依次得到旧版和新版, got %v", ids)
77		}
78	
79		got, err = b.VersionsInRange("seat", rngV2Start,
80			time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
81		if err != nil {
82			t.Fatalf("3 月 10 日至 25 日不应报错: %v", err)
83		}
84		if ids := rangeIDs(got); !equalIDs(ids, "seat-v2") {
85			t.Fatalf("3 月 10 日至 25 日应只得到新版, got %v", ids)
86		}
87	
88		got, err = b.VersionsInRange("seat", rngV2End,
89			time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
90		if err != nil {
91			t.Fatalf("3 月 20 日至 25 日不应报错: %v", err)
92		}
93		if len(got) != 0 {
94			t.Fatalf("3 月 20 日至 25 日应为空列表, got %v", rangeIDs(got))
95		}
96	}
97	
98	// 边界：范围含开始时刻、不含结束时刻；版本与范围仅在边界处相接不算命中。
99	func TestVersionsInRangeBoundaries(t *testing.T) {
100		b := newRangeBook(t)
101	
102		cases := []struct {
103			name string
104			from time.Time
105			to   time.Time
106			want []string
107		}{
108			// 范围结束即新版开始：只与旧版相交，新版只是相接。
109			{"范围结束即新版开始", time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC), rngV2Start, []string{"seat-v1"}},
110			// 范围开始即新版开始：新版命中（开始时刻含）。
111			{"范围开始即新版开始", rngV2Start, time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC), []string{"seat-v2"}},
112			// 范围开始即新版结束：新版只是相接，不命中。
113			{"范围开始即新版结束", rngV2End, time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC), []string{}},
114			// 范围结束即新版结束：新版命中（结束时刻不含，但区间内仍有生效时间）。
115			{"范围结束即新版结束", time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC), rngV2End, []string{"seat-v2"}},
116			// 范围结束即旧版开始：旧版只是相接，不命中。
117			{"范围结束即旧版开始", time.Date(2026, 2, 20, 0, 0, 0, 0, time.UTC), rngV1Start, []string{}},
118			// 范围开始即旧版开始：旧版命中。
119			{"范围开始即旧版开始", rngV1Start, time.Date(2026, 3, 2, 0, 0, 0, 0, time.UTC), []string{"seat-v1"}},
120			// 交接点本身落在范围内：旧版实际区间止于交接点（不含），新版从交接点起（含），
121			// 范围跨过交接点时两版都命中。
122			{"范围跨过交接点", rngV2Start.Add(-time.Nanosecond), rngV2Start.Add(time.Nanosecond), []string{"seat-v1", "seat-v2"}},
123			// 单纳秒范围恰在交接点：只命中新版。
124			{"交接点上的单纳秒范围", rngV2Start, rngV2Start.Add(time.Nanosecond), []string{"seat-v2"}},
125			// 单纳秒范围恰在新版结束点：无命中。
126			{"新版结束点上的单纳秒范围", rngV2End, rngV2End.Add(time.Nanosecond), []string{}},
127		}
128		for _, c := range cases {
129			got, err := b.VersionsInRange("seat", c.from, c.to)
130			if err != nil {
131				t.Fatalf("%s: 不应报错, got %v", c.name, err)
132			}
133			if ids := rangeIDs(got); !equalIDs(ids, c.want...) {
134				t.Fatalf("%s: got %v, want %v", c.name, ids, c.want)
135			}
136		}
137	}
