139	// 被替代的旧版按截短后的实际结束参与判断：登记结束（3 月 31 日）落在范围内
140	// 也不能列入；新版到期后旧版不恢复，范围完全落在空档时为空。
141	func TestVersionsInRangeTruncatedOldVersion(t *testing.T) {
142		b := newRangeBook(t)
143	
144		// 范围完全在旧版登记结束之前、但晚于交接点：旧版登记结束仍在范围内，
145		// 实际结束却是 3 月 10 日，只能列出新版。
146		got, err := b.VersionsInRange("seat",
147			time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC),
148			time.Date(2026, 3, 18, 0, 0, 0, 0, time.UTC))
149		if err != nil {
150			t.Fatal(err)
151		}
152		if ids := rangeIDs(got); !equalIDs(ids, "seat-v2") {
153			t.Fatalf("旧版登记结束在范围内也不能列入已截短的旧版: %v", ids)
154		}
155	
156		// 新版到期后：范围落在两版之后的空档，旧版不恢复，列表为空。
157		got, err = b.VersionsInRange("seat",
158			time.Date(2026, 3, 21, 0, 0, 0, 0, time.UTC),
159			rngV1End)
160		if err != nil {
161			t.Fatal(err)
162		}
163		if len(got) != 0 {
164			t.Fatalf("新版到期后旧版不能恢复: %v", rangeIDs(got))
165		}
166	}
