168	// 持续有效（无结束边界）的版本按没有结束边界处理：任意未来范围都命中。
169	func TestVersionsInRangeOpenEnded(t *testing.T) {
170		b := NewBook()
171		if err := b.RegisterVersion(RegisterRequest{
172			ItemID: "open", VersionID: "v1", UnitPrice: 7,
173			Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
174		}); err != nil {
175			t.Fatal(err)
176		}
177		got, err := b.VersionsInRange("open",
178			time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC),
179			time.Date(2099, 2, 1, 0, 0, 0, 0, time.UTC))
180		if err != nil {
181			t.Fatal(err)
182		}
183		if ids := rangeIDs(got); !equalIDs(ids, "v1") {
184			t.Fatalf("持续有效版本应命中任意未来范围: %v", ids)
185		}
186		if got[0].EffectiveEnd != nil || got[0].End != nil {
187			t.Fatalf("持续有效版本视图不应出现结束边界: %+v", got[0])
188		}
189	
190		// 范围结束即版本开始：只是相接，不命中。
191		got, err = b.VersionsInRange("open",
192			time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC),
193			time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC))
194		if err != nil {
195			t.Fatal(err)
196		}
197		if len(got) != 0 {
198			t.Fatalf("范围结束即版本开始不应命中: %v", rangeIDs(got))
199		}
200	}
201	
202	// 结束不晚于开始时一律返回可明确识别的范围错误，不返回版本列表；
203	// 即使费率项从未登记过，范围错误也优先。
204	func TestVersionsInRangeInvalidRange(t *testing.T) {
205		b := newRangeBook(t)
206	
207		at := time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC)
208		for _, c := range []struct {
209			name string
210			from time.Time
211			to   time.Time
212		}{
213			{"结束等于开始", at, at},
214			{"结束早于开始", at, at.Add(-time.Nanosecond)},
215			{"结束远早于开始", rngV2End, rngV1Start},
216		} {
217			got, err := b.VersionsInRange("seat", c.from, c.to)
218			if !errors.Is(err, ErrInvalidRange) {
219				t.Fatalf("%s: want ErrInvalidRange, got %v", c.name, err)
220			}
221			if got != nil {
222				t.Fatalf("%s: 范围错误不应返回版本列表, got %v", c.name, rangeIDs(got))
223			}
224			// 同一瞬间的不同时区表示结论一致。
225			got, err = b.VersionsInRange("seat", c.from.In(east8), c.to.In(east8))
226			if !errors.Is(err, ErrInvalidRange) {
227				t.Fatalf("%s（东八区表示）: want ErrInvalidRange, got %v", c.name, err)
228			}
229			if got != nil {
230				t.Fatalf("%s（东八区表示）: 范围错误不应返回版本列表, got %v", c.name, rangeIDs(got))
231			}
232		}
233	
234		// 费率项不存在时，范围错误同样优先于未找到错误。
235		_, err := b.VersionsInRange("never-seen", at, at)
236		if !errors.Is(err, ErrInvalidRange) {
237			t.Fatalf("项不存在时范围错误仍应优先: got %v", err)
238		}
239	}
240	
241	// 范围合法但费率项从未登记过版本时，沿用现有的费率项未找到错误；
242	// 费率项存在但范围内没有命中版本时，返回空列表且不报错。
243	func TestVersionsInRangeMissingItemVsEmptyResult(t *testing.T) {
244		b := newRangeBook(t)
245	
246		_, err := b.VersionsInRange("never-seen", rngV1Start, rngV2Start)
247		if !errors.Is(err, ErrItemNotFound) {
248			t.Fatalf("从未登记的费率项应返回 ErrItemNotFound, got %v", err)
249		}
250		if errors.Is(err, ErrInvalidRange) {
251			t.Fatalf("合法范围不能被误报成范围错误: %v", err)
252		}
253	
254		got, err := b.VersionsInRange("seat",
255			time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC),
256			time.Date(2026, 2, 15, 0, 0, 0, 0, time.UTC))
257		if err != nil {
258			t.Fatalf("项存在但无命中不应报错: %v", err)
259		}
260		if got == nil || len(got) != 0 {
261			t.Fatalf("项存在但无命中应返回空列表: %+v", got)
262		}
263		if errors.Is(err, ErrItemNotFound) {
264			t.Fatalf("无命中不能被误报成费率项不存在: %v", err)
265		}
266	}
267	
268	// 空档不补入相邻版本：范围覆盖两段版本之间的空档时，只列出实际相交的版本。
269	func TestVersionsInRangeGapNotFilled(t *testing.T) {
270		b := NewBook()
271		must := func(r RegisterRequest) {
272			t.Helper()
273			if err := b.RegisterVersion(r); err != nil {
274				t.Fatalf("register %+v: %v", r, err)
275			}
276		}
277		// 两段不涉及替代的区间，中间留 3 月 10 日至 3 月 20 日的空档。
278		must(RegisterRequest{
279			ItemID: "gap", VersionID: "g1", UnitPrice: 100,
280			Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
281			End:   ptrTime(time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)),
282		})
283		must(RegisterRequest{
284			ItemID: "gap", VersionID: "g2", UnitPrice: 200,
285			Start: time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC),
286			End:   ptrTime(time.Date(2026, 3, 30, 0, 0, 0, 0, time.UTC)),
287		})
288	
289		// 范围跨过整个空档：两段都命中，空档本身不产生任何版本。
290		got, err := b.VersionsInRange("gap",
291			time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC),
292			time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
293		if err != nil {
294			t.Fatal(err)
295		}
296		if ids := rangeIDs(got); !equalIDs(ids, "g1", "g2") {
297			t.Fatalf("跨过空档的范围应只列出实际相交的两版: %v", ids)
298		}
299	
300		// 范围完全落在空档内：空列表，不拿相邻版本补位。
301		got, err = b.VersionsInRange("gap",
302			time.Date(2026, 3, 12, 0, 0, 0, 0, time.UTC),
303			time.Date(2026, 3, 18, 0, 0, 0, 0, time.UTC))
304		if err != nil {
305			t.Fatal(err)
306		}
307		if len(got) != 0 {
308			t.Fatalf("空档内不应补入相邻版本: %v", rangeIDs(got))
309		}
310	}
311	
312	// 返回列表沿用现有版本视图：保留登记起止、实际有效区间和替代关系，
313	// 不把版本边界改成查询范围的边界；按实际生效起点从早到晚排列，每版只出现一次。
314	func TestVersionsInRangeViewFieldsAndOrdering(t *testing.T) {
315		b := newRangeBook(t)
316	
317		got, err := b.VersionsInRange("seat",
318			time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
319			time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
320		if err != nil {
321			t.Fatal(err)
322		}
323		if len(got) != 2 {
324			t.Fatalf("应命中两版, got %v", rangeIDs(got))
325		}
326	
327		old, nv := got[0], got[1]
328		if old.VersionID != "seat-v1" || nv.VersionID != "seat-v2" {
329			t.Fatalf("应按实际生效起点从早到晚排列: %v", rangeIDs(got))
330		}
331	
332		// 旧版保留登记边界与截短后的实际边界，不被查询范围 [3-09, 3-11) 改写。
333		if old.ItemID != "seat" || old.UnitPrice != 150 {
334			t.Fatalf("旧版标识/单价异常: %+v", old)
335		}
336		if !old.Start.Equal(rngV1Start) || !old.EffectiveStart.Equal(rngV1Start) {
337			t.Fatalf("旧版开始边界不应被改成范围开始: %+v", old)
338		}
339		if old.End == nil || !old.End.Equal(rngV1End) {
340			t.Fatalf("旧版应保留登记结束 3 月 31 日: %v", old.End)
341		}
342		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(rngV2Start) {
343			t.Fatalf("旧版实际结束应显示交接点 3 月 10 日: %v", old.EffectiveEnd)
344		}
345		if old.Replaces != "" || old.SupersededBy != "seat-v2" {
346			t.Fatalf("旧版替代关系异常: Replaces=%q SupersededBy=%q", old.Replaces, old.SupersededBy)
347		}
348	
349		if nv.UnitPrice != 180 || !nv.Start.Equal(rngV2Start) || !nv.EffectiveStart.Equal(rngV2Start) {
350			t.Fatalf("新版视图异常: %+v", nv)
351		}
352		if nv.End == nil || !nv.End.Equal(rngV2End) || nv.EffectiveEnd == nil || !nv.EffectiveEnd.Equal(rngV2End) {
353			t.Fatalf("新版结束边界不应被改成范围结束: %+v", nv)
354		}
355		if nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
356			t.Fatalf("新版替代关系异常: Replaces=%q SupersededBy=%q", nv.Replaces, nv.SupersededBy)
357		}
358	
359		// 无论范围与版本相交多少次，每个版本只出现一次：大范围包含两版完整区间。
360		got, err = b.VersionsInRange("seat",
361			time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
362			time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC))
363		if err != nil {
364			t.Fatal(err)
365		}
366		if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
367			t.Fatalf("大范围应各列一次、按起点排序: %v", ids)
368		}
369	}
