371	// 同一瞬间用不同时区表示，范围查询结论一致。
372	func TestVersionsInRangeSameInstantAnyTimezone(t *testing.T) {
373		b := newRangeBook(t)
374	
375		from := time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC)
376		to := time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC)
377		reprs := [][2]time.Time{
378			{from, to},
379			{from.In(east8), to.In(east8)},
380			{from.In(time.FixedZone("UTC-5", -5*3600)), to.In(time.FixedZone("UTC-5", -5*3600))},
381		}
382		for i, r := range reprs {
383			got, err := b.VersionsInRange("seat", r[0], r[1])
384			if err != nil {
385				t.Fatalf("表示%d: %v", i, err)
386			}
387			if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
388				t.Fatalf("表示%d: got %v, want [seat-v1 seat-v2]", i, ids)
389			}
390		}
391	}
