393	// 选择只在指定费率项内进行：其他费率项即使有同名版本也不参与。
394	func TestVersionsInRangeScopedToItem(t *testing.T) {
395		b := NewBook()
396		must := func(r RegisterRequest) {
397			t.Helper()
398			if err := b.RegisterVersion(r); err != nil {
399				t.Fatalf("register %+v: %v", r, err)
400			}
401		}
402		must(RegisterRequest{
403			ItemID: "seat", VersionID: "v1", UnitPrice: 150,
404			Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
405			End:   ptrTime(time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)),
406		})
407		must(RegisterRequest{
