418		if len(got) != 1 || got[0].ItemID != "seat" || got[0].UnitPrice != 150 {
419			t.Fatalf("seat 的范围查询不能混入 room 的同名版本: %+v", got)
420		}
421	
422		got, err = b.VersionsInRange("room",
423			time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
424			time.Date(2026, 4, 15, 0, 0, 0, 0, time.UTC))
425		if err != nil {
