429			t.Fatalf("room 的范围查询不能混入 seat 的同名版本: %+v", got)
430		}
431	}
432	
433	// 范围可以在过去或未来，与账本受理时钟无关。
434	func TestVersionsInRangeIgnoresLedgerClock(t *testing.T) {
435		now, setNow := fixedClock(time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC))
436		b := NewBook(WithClock(now))
