452		if ids := rangeIDs(got); !equalIDs(ids, "seat-v1") {
453			t.Fatalf("时钟在未来不影响查过去: %v", ids)
454		}
455	
456		// 时钟拨回登记之前，查未来的范围结论不变。
457		setNow(time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC))
458		got, err = b.VersionsInRange("seat",
459			time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC),
