package tariff

import (
	"errors"
	"fmt"
	"sync"
	"testing"
	"time"
)

// VersionsInRange 场景的固定时间线（UTC，结束时刻均不含）：
//
//	旧版 seat-v1：单价 150 分，2026-03-01 00:00 起生效，登记结束 2026-03-31 00:00
//	新版 seat-v2：单价 180 分，2026-03-10 00:00 起替代旧版，2026-03-20 00:00 结束
//
// 查询时旧版的实际有效区间已被截断到 3 月 10 日。
var (
	rngV1Start = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
	rngV1End   = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
	rngV2Start = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
	rngV2End   = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)
)

func newRangeBook(t *testing.T) *Book {
	t.Helper()
	b := NewBook()
	v1End := rngV1End
	if err := b.RegisterVersion(RegisterRequest{
		ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
		Start: rngV1Start, End: &v1End,
	}); err != nil {
		t.Fatalf("register seat-v1: %v", err)
	}
	v2End := rngV2End
	if err := b.RegisterVersion(RegisterRequest{
		ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
		Start: rngV2Start, End: &v2End, Replaces: "seat-v1",
	}); err != nil {
		t.Fatalf("register seat-v2: %v", err)
	}
	return b
}

func rangeIDs(views []VersionView) []string {
	ids := make([]string, len(views))
	for i, v := range views {
		ids[i] = v.VersionID
	}
	return ids
}

func equalIDs(got []string, want ...string) bool {
	if len(got) != len(want) {
		return false
	}
	for i := range want {
		if got[i] != want[i] {
			return false
		}
	}
	return true
}

// 题目示例：查看 3 月 9 日至 3 月 11 日应得到旧版和新版；
// 查看 3 月 10 日至 3 月 25 日只得到新版；查看 3 月 20 日至 3 月 25 日为空。
func TestVersionsInRangeSpecExample(t *testing.T) {
	b := newRangeBook(t)

	got, err := b.VersionsInRange("seat",
		time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatalf("3 月 9 日至 11 日不应报错: %v", err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
		t.Fatalf("3 月 9 日至 11 日应依次得到旧版和新版, got %v", ids)
	}

	got, err = b.VersionsInRange("seat", rngV2Start,
		time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatalf("3 月 10 日至 25 日不应报错: %v", err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "seat-v2") {
		t.Fatalf("3 月 10 日至 25 日应只得到新版, got %v", ids)
	}

	got, err = b.VersionsInRange("seat", rngV2End,
		time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatalf("3 月 20 日至 25 日不应报错: %v", err)
	}
	if len(got) != 0 {
		t.Fatalf("3 月 20 日至 25 日应为空列表, got %v", rangeIDs(got))
	}
}

// 边界：范围含开始时刻、不含结束时刻；版本与范围仅在边界处相接不算命中。
func TestVersionsInRangeBoundaries(t *testing.T) {
	b := newRangeBook(t)

	cases := []struct {
		name string
		from time.Time
		to   time.Time
		want []string
	}{
		// 范围结束即新版开始：只与旧版相交，新版只是相接。
		{"范围结束即新版开始", time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC), rngV2Start, []string{"seat-v1"}},
		// 范围开始即新版开始：新版命中（开始时刻含）。
		{"范围开始即新版开始", rngV2Start, time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC), []string{"seat-v2"}},
		// 范围开始即新版结束：新版只是相接，不命中。
		{"范围开始即新版结束", rngV2End, time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC), []string{}},
		// 范围结束即新版结束：新版命中（结束时刻不含，但区间内仍有生效时间）。
		{"范围结束即新版结束", time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC), rngV2End, []string{"seat-v2"}},
		// 范围结束即旧版开始：旧版只是相接，不命中。
		{"范围结束即旧版开始", time.Date(2026, 2, 20, 0, 0, 0, 0, time.UTC), rngV1Start, []string{}},
		// 范围开始即旧版开始：旧版命中。
		{"范围开始即旧版开始", rngV1Start, time.Date(2026, 3, 2, 0, 0, 0, 0, time.UTC), []string{"seat-v1"}},
		// 交接点本身落在范围内：旧版实际区间止于交接点（不含），新版从交接点起（含），
		// 范围跨过交接点时两版都命中。
		{"范围跨过交接点", rngV2Start.Add(-time.Nanosecond), rngV2Start.Add(time.Nanosecond), []string{"seat-v1", "seat-v2"}},
		// 单纳秒范围恰在交接点：只命中新版。
		{"交接点上的单纳秒范围", rngV2Start, rngV2Start.Add(time.Nanosecond), []string{"seat-v2"}},
		// 单纳秒范围恰在新版结束点：无命中。
		{"新版结束点上的单纳秒范围", rngV2End, rngV2End.Add(time.Nanosecond), []string{}},
	}
	for _, c := range cases {
		got, err := b.VersionsInRange("seat", c.from, c.to)
		if err != nil {
			t.Fatalf("%s: 不应报错, got %v", c.name, err)
		}
		if ids := rangeIDs(got); !equalIDs(ids, c.want...) {
			t.Fatalf("%s: got %v, want %v", c.name, ids, c.want)
		}
	}
}

// 被替代的旧版按截短后的实际结束参与判断：登记结束（3 月 31 日）落在范围内
// 也不能列入；新版到期后旧版不恢复，范围完全落在空档时为空。
func TestVersionsInRangeTruncatedOldVersion(t *testing.T) {
	b := newRangeBook(t)

	// 范围完全在旧版登记结束之前、但晚于交接点：旧版登记结束仍在范围内，
	// 实际结束却是 3 月 10 日，只能列出新版。
	got, err := b.VersionsInRange("seat",
		time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 18, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "seat-v2") {
		t.Fatalf("旧版登记结束在范围内也不能列入已截短的旧版: %v", ids)
	}

	// 新版到期后：范围落在两版之后的空档，旧版不恢复，列表为空。
	got, err = b.VersionsInRange("seat",
		time.Date(2026, 3, 21, 0, 0, 0, 0, time.UTC),
		rngV1End)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 0 {
		t.Fatalf("新版到期后旧版不能恢复: %v", rangeIDs(got))
	}
}

// 持续有效（无结束边界）的版本按没有结束边界处理：任意未来范围都命中。
func TestVersionsInRangeOpenEnded(t *testing.T) {
	b := NewBook()
	if err := b.RegisterVersion(RegisterRequest{
		ItemID: "open", VersionID: "v1", UnitPrice: 7,
		Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
	}); err != nil {
		t.Fatal(err)
	}
	got, err := b.VersionsInRange("open",
		time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC),
		time.Date(2099, 2, 1, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "v1") {
		t.Fatalf("持续有效版本应命中任意未来范围: %v", ids)
	}
	if got[0].EffectiveEnd != nil || got[0].End != nil {
		t.Fatalf("持续有效版本视图不应出现结束边界: %+v", got[0])
	}

	// 范围结束即版本开始：只是相接，不命中。
	got, err = b.VersionsInRange("open",
		time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 0 {
		t.Fatalf("范围结束即版本开始不应命中: %v", rangeIDs(got))
	}
}

// 结束不晚于开始时一律返回可明确识别的范围错误，不返回版本列表；
// 即使费率项从未登记过，范围错误也优先。
func TestVersionsInRangeInvalidRange(t *testing.T) {
	b := newRangeBook(t)

	at := time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC)
	for _, c := range []struct {
		name string
		from time.Time
		to   time.Time
	}{
		{"结束等于开始", at, at},
		{"结束早于开始", at, at.Add(-time.Nanosecond)},
		{"结束远早于开始", rngV2End, rngV1Start},
	} {
		got, err := b.VersionsInRange("seat", c.from, c.to)
		if !errors.Is(err, ErrInvalidRange) {
			t.Fatalf("%s: want ErrInvalidRange, got %v", c.name, err)
		}
		if got != nil {
			t.Fatalf("%s: 范围错误不应返回版本列表, got %v", c.name, rangeIDs(got))
		}
		// 同一瞬间的不同时区表示结论一致。
		got, err = b.VersionsInRange("seat", c.from.In(east8), c.to.In(east8))
		if !errors.Is(err, ErrInvalidRange) {
			t.Fatalf("%s（东八区表示）: want ErrInvalidRange, got %v", c.name, err)
		}
		if got != nil {
			t.Fatalf("%s（东八区表示）: 范围错误不应返回版本列表, got %v", c.name, rangeIDs(got))
		}
	}

	// 费率项不存在时，范围错误同样优先于未找到错误。
	_, err := b.VersionsInRange("never-seen", at, at)
	if !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("项不存在时范围错误仍应优先: got %v", err)
	}
}

// 范围合法但费率项从未登记过版本时，沿用现有的费率项未找到错误；
// 费率项存在但范围内没有命中版本时，返回空列表且不报错。
func TestVersionsInRangeMissingItemVsEmptyResult(t *testing.T) {
	b := newRangeBook(t)

	_, err := b.VersionsInRange("never-seen", rngV1Start, rngV2Start)
	if !errors.Is(err, ErrItemNotFound) {
		t.Fatalf("从未登记的费率项应返回 ErrItemNotFound, got %v", err)
	}
	if errors.Is(err, ErrInvalidRange) {
		t.Fatalf("合法范围不能被误报成范围错误: %v", err)
	}

	got, err := b.VersionsInRange("seat",
		time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 2, 15, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatalf("项存在但无命中不应报错: %v", err)
	}
	if got == nil || len(got) != 0 {
		t.Fatalf("项存在但无命中应返回空列表: %+v", got)
	}
	if errors.Is(err, ErrItemNotFound) {
		t.Fatalf("无命中不能被误报成费率项不存在: %v", err)
	}
}

// 空档不补入相邻版本：范围覆盖两段版本之间的空档时，只列出实际相交的版本。
func TestVersionsInRangeGapNotFilled(t *testing.T) {
	b := NewBook()
	must := func(r RegisterRequest) {
		t.Helper()
		if err := b.RegisterVersion(r); err != nil {
			t.Fatalf("register %+v: %v", r, err)
		}
	}
	// 两段不涉及替代的区间，中间留 3 月 10 日至 3 月 20 日的空档。
	must(RegisterRequest{
		ItemID: "gap", VersionID: "g1", UnitPrice: 100,
		Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
		End:   ptrTime(time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)),
	})
	must(RegisterRequest{
		ItemID: "gap", VersionID: "g2", UnitPrice: 200,
		Start: time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC),
		End:   ptrTime(time.Date(2026, 3, 30, 0, 0, 0, 0, time.UTC)),
	})

	// 范围跨过整个空档：两段都命中，空档本身不产生任何版本。
	got, err := b.VersionsInRange("gap",
		time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "g1", "g2") {
		t.Fatalf("跨过空档的范围应只列出实际相交的两版: %v", ids)
	}

	// 范围完全落在空档内：空列表，不拿相邻版本补位。
	got, err = b.VersionsInRange("gap",
		time.Date(2026, 3, 12, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 18, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 0 {
		t.Fatalf("空档内不应补入相邻版本: %v", rangeIDs(got))
	}
}

// 返回列表沿用现有版本视图：保留登记起止、实际有效区间和替代关系，
// 不把版本边界改成查询范围的边界；按实际生效起点从早到晚排列，每版只出现一次。
func TestVersionsInRangeViewFieldsAndOrdering(t *testing.T) {
	b := newRangeBook(t)

	got, err := b.VersionsInRange("seat",
		time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 {
		t.Fatalf("应命中两版, got %v", rangeIDs(got))
	}

	old, nv := got[0], got[1]
	if old.VersionID != "seat-v1" || nv.VersionID != "seat-v2" {
		t.Fatalf("应按实际生效起点从早到晚排列: %v", rangeIDs(got))
	}

	// 旧版保留登记边界与截短后的实际边界，不被查询范围 [3-09, 3-11) 改写。
	if old.ItemID != "seat" || old.UnitPrice != 150 {
		t.Fatalf("旧版标识/单价异常: %+v", old)
	}
	if !old.Start.Equal(rngV1Start) || !old.EffectiveStart.Equal(rngV1Start) {
		t.Fatalf("旧版开始边界不应被改成范围开始: %+v", old)
	}
	if old.End == nil || !old.End.Equal(rngV1End) {
		t.Fatalf("旧版应保留登记结束 3 月 31 日: %v", old.End)
	}
	if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(rngV2Start) {
		t.Fatalf("旧版实际结束应显示交接点 3 月 10 日: %v", old.EffectiveEnd)
	}
	if old.Replaces != "" || old.SupersededBy != "seat-v2" {
		t.Fatalf("旧版替代关系异常: Replaces=%q SupersededBy=%q", old.Replaces, old.SupersededBy)
	}

	if nv.UnitPrice != 180 || !nv.Start.Equal(rngV2Start) || !nv.EffectiveStart.Equal(rngV2Start) {
		t.Fatalf("新版视图异常: %+v", nv)
	}
	if nv.End == nil || !nv.End.Equal(rngV2End) || nv.EffectiveEnd == nil || !nv.EffectiveEnd.Equal(rngV2End) {
		t.Fatalf("新版结束边界不应被改成范围结束: %+v", nv)
	}
	if nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
		t.Fatalf("新版替代关系异常: Replaces=%q SupersededBy=%q", nv.Replaces, nv.SupersededBy)
	}

	// 无论范围与版本相交多少次，每个版本只出现一次：大范围包含两版完整区间。
	got, err = b.VersionsInRange("seat",
		time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
		time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
		t.Fatalf("大范围应各列一次、按起点排序: %v", ids)
	}
}

// 同一瞬间用不同时区表示，范围查询结论一致。
func TestVersionsInRangeSameInstantAnyTimezone(t *testing.T) {
	b := newRangeBook(t)

	from := time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC)
	to := time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC)
	reprs := [][2]time.Time{
		{from, to},
		{from.In(east8), to.In(east8)},
		{from.In(time.FixedZone("UTC-5", -5*3600)), to.In(time.FixedZone("UTC-5", -5*3600))},
	}
	for i, r := range reprs {
		got, err := b.VersionsInRange("seat", r[0], r[1])
		if err != nil {
			t.Fatalf("表示%d: %v", i, err)
		}
		if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
			t.Fatalf("表示%d: got %v, want [seat-v1 seat-v2]", i, ids)
		}
	}
}

// 选择只在指定费率项内进行：其他费率项即使有同名版本也不参与。
func TestVersionsInRangeScopedToItem(t *testing.T) {
	b := NewBook()
	must := func(r RegisterRequest) {
		t.Helper()
		if err := b.RegisterVersion(r); err != nil {
			t.Fatalf("register %+v: %v", r, err)
		}
	}
	must(RegisterRequest{
		ItemID: "seat", VersionID: "v1", UnitPrice: 150,
		Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
		End:   ptrTime(time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)),
	})
	must(RegisterRequest{
		ItemID: "room", VersionID: "v1", UnitPrice: 300,
		Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
	})

	got, err := b.VersionsInRange("seat",
		time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 4, 15, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0].ItemID != "seat" || got[0].UnitPrice != 150 {
		t.Fatalf("seat 的范围查询不能混入 room 的同名版本: %+v", got)
	}

	got, err = b.VersionsInRange("room",
		time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 4, 15, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0].ItemID != "room" || got[0].UnitPrice != 300 {
		t.Fatalf("room 的范围查询不能混入 seat 的同名版本: %+v", got)
	}
}

// 范围可以在过去或未来，与账本受理时钟无关。
func TestVersionsInRangeIgnoresLedgerClock(t *testing.T) {
	now, setNow := fixedClock(time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC))
	b := NewBook(WithClock(now))
	v1End := rngV1End
	if err := b.RegisterVersion(RegisterRequest{
		ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
		Start: rngV1Start, End: &v1End,
	}); err != nil {
		t.Fatal(err)
	}

	// 时钟停在 6 月，查过去的范围仍按登记区间回答。
	got, err := b.VersionsInRange("seat",
		time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 6, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "seat-v1") {
		t.Fatalf("时钟在未来不影响查过去: %v", ids)
	}

	// 时钟拨回登记之前，查未来的范围结论不变。
	setNow(time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC))
	got, err = b.VersionsInRange("seat",
		time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 6, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "seat-v1") {
		t.Fatalf("时钟在过去不影响查未来: %v", ids)
	}
}

// 选择依据是查询时账本已登记的版本：补登过去生效的替代版本后，
// 同一历史范围的回答按当前登记的实际区间变化。
func TestVersionsInRangeReflectsRetroactiveRegistration(t *testing.T) {
	b := NewBook()
	v1End := rngV1End
	if err := b.RegisterVersion(RegisterRequest{
		ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
		Start: rngV1Start, End: &v1End,
	}); err != nil {
		t.Fatal(err)
	}

	from := time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC)
	to := time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC)
	got, err := b.VersionsInRange("seat", from, to)
	if err != nil {
		t.Fatal(err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "seat-v1") {
		t.Fatalf("补登前该范围只应命中旧版: %v", ids)
	}

	// 补登 3 月 10 日起生效的替代版本后，旧版实际区间被截断，同一范围命中两版。
	if err := b.RegisterVersion(RegisterRequest{
		ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
		Start: rngV2Start, Replaces: "seat-v1",
	}); err != nil {
		t.Fatal(err)
	}
	got, err = b.VersionsInRange("seat", from, to)
	if err != nil {
		t.Fatal(err)
	}
	if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
		t.Fatalf("补登后同一范围应按当前登记区间命中两版: %v", ids)
	}
}

// 查询是只读操作：不受理报价、不占用请求标识；
// 返回视图是独立副本，改写其中的结束时间不影响后续查询和报价。
func TestVersionsInRangeReadOnlyAndIsolated(t *testing.T) {
	b, setNow := newEffectiveVersionBook(t, effV1Start)

	got, err := b.VersionsInRange("seat",
		time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 {
		t.Fatalf("前提：应命中两版, got %v", rangeIDs(got))
	}

	// 调用方改写返回视图中的结束时间。
	*got[0].End = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
	*got[0].EffectiveEnd = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
	*got[1].End = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
	*got[1].EffectiveEnd = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)

	// 再次范围查询：边界仍是账本原值，且与上次返回不共享指针。
	again, err := b.VersionsInRange("seat",
		time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	if again[0].End == nil || !again[0].End.Equal(effV1End) {
		t.Fatalf("登记结束被查询结果的修改改写: %v", again[0].End)
	}
	if again[0].EffectiveEnd == nil || !again[0].EffectiveEnd.Equal(effV2Start) {
		t.Fatalf("实际结束被查询结果的修改改写: %v", again[0].EffectiveEnd)
	}
	if got[0].End == again[0].End || got[0].EffectiveEnd == again[0].EffectiveEnd {
		t.Fatal("两次范围查询共享了结束时间指针")
	}

	// 其他查询入口同样未被污染。
	view, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC))
	if err != nil || view.EffectiveEnd == nil || !view.EffectiveEnd.Equal(effV2Start) {
		t.Fatalf("EffectiveVersionAt 被范围查询结果的修改污染: %+v (%v)", view, err)
	}

	// 报价仍按账本真实区间处理：交接点起旧版失效、新版有效。
	setNow(effV2Start)
	out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "seat-v1", Quantity: 1})
	if out.Confirmed || out.Reason != ReasonVersionExpired {
		t.Fatalf("修改范围查询结果不能影响后续报价依据: %+v", out)
	}
	out, _ = b.Quote(QuoteRequest{RequestID: "q-new", ItemID: "seat", VersionID: "seat-v2", Quantity: 1})
	if !out.Confirmed {
		t.Fatalf("新版在交接点应可报价: %+v", out)
	}

	// 范围查询本身不产生任何报价记录、不占用请求标识。
	if _, err := b.Lookup("range-query-check"); !errors.Is(err, ErrRequestNotFound) {
		t.Fatalf("只读查询不应产生报价记录: %v", err)
	}
	fresh, err := b.Quote(QuoteRequest{RequestID: "range-query-check", ItemID: "seat", VersionID: "seat-v2", Quantity: 2})
	if err != nil || !fresh.Confirmed || fresh.Total != 360 {
		t.Fatalf("范围查询不应占用请求标识或影响首次受理: %+v (%v)", fresh, err)
	}
}

// 并发只读范围查询应始终给出一致结论。
func TestVersionsInRangeConcurrentReads(t *testing.T) {
	b := newRangeBook(t)

	const n = 32
	var wg sync.WaitGroup
	errs := make(chan error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			got, err := b.VersionsInRange("seat",
				time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
				time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
			if err != nil {
				errs <- fmt.Errorf("查询 %d: %w", i, err)
				return
			}
			if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
				errs <- fmt.Errorf("查询 %d 结果异常: %v", i, ids)
			}
		}(i)
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Error(err)
	}
}

package tariff

import (
	"errors"
	"math"
	"sort"
	"sync"
	"time"
)

// 登记费率版本时可能返回的错误。
var (
	ErrEmptyItemID            = errors.New("tariff: item id must not be empty")
	ErrEmptyVersionID         = errors.New("tariff: version id must not be empty")
	ErrInvalidUnitPrice       = errors.New("tariff: unit price must not be negative")
	ErrStartRequired          = errors.New("tariff: effective start time is required")
	ErrInvalidInterval        = errors.New("tariff: end time must be after start time")
	ErrVersionExists          = errors.New("tariff: version id already registered for the item")
	ErrOverlap                = errors.New("tariff: version interval overlaps an existing version of the item")
	ErrReplaceTargetNotFound  = errors.New("tariff: replaced version does not exist")
	ErrReplaceTargetWrongItem = errors.New("tariff: replaced version belongs to another item")
	ErrInvalidReplacement     = errors.New("tariff: new version start must be after the replaced version start and within its current effective interval")
)

// 查询与报价时可能返回的错误。
var (
	ErrItemNotFound       = errors.New("tariff: rate item not found")
	ErrNoEffectiveVersion = errors.New("tariff: no effective version for the rate item at the given time")
	ErrRequestNotFound    = errors.New("tariff: request id not found")
	ErrRequestIDConflict  = errors.New("tariff: request id already used with different content")
	ErrEmptyItemIDQuery   = errors.New("tariff: item id must not be empty")
	ErrInvalidRange       = errors.New("tariff: range end must be after range start")
)

// RejectReason 区分报价被拒绝的原因。
type RejectReason string

const (
	ReasonNone                   RejectReason = ""
	ReasonEmptyRequestID         RejectReason = "empty_request_id"
	ReasonInvalidQuantity        RejectReason = "invalid_quantity"
	ReasonVersionNotFound        RejectReason = "version_not_found"
	ReasonVersionNotYetEffective RejectReason = "version_not_yet_effective"
	ReasonVersionExpired         RejectReason = "version_expired"
	ReasonTotalOverflow          RejectReason = "total_overflow"
)

// RegisterRequest 描述一次费率版本登记。
type RegisterRequest struct {
	ItemID    string
	VersionID string
	UnitPrice int64      // 整数分单价，可以为零，不能为负
	Start     time.Time  // 必填，生效时刻（含）
	End       *time.Time // 可选，结束时刻（不含）；nil 表示持续有效
	Replaces  string     // 可选，同项内被本版本替代的旧版本标识
}

// VersionView 是查询费率项时返回的版本视图，
// 同时包含登记的起止时间、替代关系和实际有效区间。
type VersionView struct {
	ItemID         string
	VersionID      string
	UnitPrice      int64
	Start          time.Time  // 登记的生效时刻（含）
	End            *time.Time // 登记的结束时刻（不含），nil 表示持续有效
	Replaces       string     // 本版本登记时替代的旧版本，空表示无
	SupersededBy   string     // 替代本版本的新版本，空表示未被替代
	EffectiveStart time.Time  // 实际有效区间起点（含）
	EffectiveEnd   *time.Time // 实际有效区间终点（不含），nil 表示持续有效
}

// QuoteRequest 描述一次报价请求。
type QuoteRequest struct {
	RequestID string // 非空请求标识，用于幂等与查询
	ItemID    string
	VersionID string
	Quantity  int64 // 正整数
}

// Outcome 是报价的首次受理结果：要么确认，要么带原因拒绝。
// 成功报价即为已确认记录，之后费率变化不会改写其中的金额和来源。
type Outcome struct {
	Request    QuoteRequest // 原请求内容
	AcceptedAt time.Time    // 首次受理时刻
	Confirmed  bool
	UnitPrice  int64        // 确认时的实际单价（分）
	Total      int64        // 确认时的总价（分）
	Reason     RejectReason // 被拒绝时的原因
}

// version 是登记在册的费率版本。effEnd 因被替代而可能早于登记的 end。
type version struct {
	itemID       string
	versionID    string
	unitPrice    int64
	start        time.Time
	end          *time.Time
	replaces     string
	supersededBy string
	effEnd       *time.Time
}

// availability 描述版本在某一瞬间的可用性，是查询与报价共用的唯一判断口径。
type availability int

const (
	availabilityEffective availability = iota // 处于实际有效区间内
	availabilityNotYet                        // 尚未到达生效起点
	availabilityExpired                       // 已过实际有效终点
)

// availabilityAt 判断版本在 t 这一瞬间是否处于实际有效区间 [start, effEnd)。
// 开始时刻包含在内，结束时刻不包含；effEnd 为 nil 表示持续有效。
// 被替代的版本以截短后的实际结束时刻（effEnd）为准，不看登记时填写的 end。
// 时间按实际时刻比较，同一瞬间的不同时区表示结论一致。
// 查询（EffectiveVersionAt）与报价（Quote）都以此为唯一判断，
// 只是各自传入的瞬间不同：查询用调用方指定的时刻，报价用首次受理时刻。
func (v *version) availabilityAt(t time.Time) availability {
	if t.Before(v.start) {
		return availabilityNotYet
	}
	if v.effEnd != nil && !t.Before(*v.effEnd) {
		return availabilityExpired
	}
	return availabilityEffective
}

// Book 是费率版本与报价的本地账本，可并发使用。
type Book struct {
	mu       sync.Mutex
	now      func() time.Time
	items    map[string]map[string]*version // itemID -> versionID -> version
	requests map[string]Outcome             // requestID -> 首次受理结果
}

// Option 定制 Book 的行为。
type Option func(*Book)

// WithClock 指定受理时刻的来源，默认使用 time.Now。
func WithClock(now func() time.Time) Option {
	return func(b *Book) {
		if now != nil {
			b.now = now
		}
	}
}

// NewBook 返回一个空的账本。
func NewBook(opts ...Option) *Book {
	b := &Book{
		now:      time.Now,
		items:    make(map[string]map[string]*version),
		requests: make(map[string]Outcome),
	}
	for _, opt := range opts {
		opt(b)
	}
	return b
}

// RegisterVersion 登记一个费率版本。任何校验失败都不会留下部分变更。
func (b *Book) RegisterVersion(req RegisterRequest) error {
	b.mu.Lock()
	defer b.mu.Unlock()

	if req.ItemID == "" {
		return ErrEmptyItemID
	}
	if req.VersionID == "" {
		return ErrEmptyVersionID
	}
	if req.UnitPrice < 0 {
		return ErrInvalidUnitPrice
	}
	if req.Start.IsZero() {
		return ErrStartRequired
	}
	if req.End != nil && !req.End.After(req.Start) {
		return ErrInvalidInterval
	}

	versions := b.items[req.ItemID]
	if _, ok := versions[req.VersionID]; ok {
		return ErrVersionExists
	}

	var target *version
	if req.Replaces != "" {
		t, ok := versions[req.Replaces]
		if !ok {
			if b.versionInOtherItem(req.ItemID, req.Replaces) {
				return ErrReplaceTargetWrongItem
			}
			return ErrReplaceTargetNotFound
		}
		// 新版本的开始必须晚于旧版本的开始，且落在旧版本当前的有效区间内。
		if !req.Start.After(t.start) {
			return ErrInvalidReplacement
		}
		if t.effEnd != nil && !req.Start.Before(*t.effEnd) {
			return ErrInvalidReplacement
		}
		target = t
	}

	// 与同项其他版本的实际有效区间比较，不允许重叠；
	// 被替代版本会被截断到新版本开始时刻，不参与重叠判断。
	for _, v := range versions {
		if v == target {
			continue
		}
		if intervalsOverlap(req.Start, req.End, v.start, v.effEnd) {
			return ErrOverlap
		}
	}

	// 全部校验通过后才提交变更。结束时刻必须复制后入库：
	// 既不能与调用方的请求变量共享指针，登记结束与实际结束之间也互为独立副本，
	// 外部对原变量或任一返回结果的修改都不能改写账本中的边界。
	v := &version{
		itemID:    req.ItemID,
		versionID: req.VersionID,
		unitPrice: req.UnitPrice,
		start:     req.Start,
		end:       cloneTimePtr(req.End),
		replaces:  req.Replaces,
		effEnd:    cloneTimePtr(req.End),
	}
	if target != nil {
		truncated := req.Start
		target.effEnd = &truncated
		target.supersededBy = req.VersionID
	}
	if versions == nil {
		versions = make(map[string]*version)
		b.items[req.ItemID] = versions
	}
	versions[req.VersionID] = v
	return nil
}

func (b *Book) versionInOtherItem(itemID, versionID string) bool {
	for id, versions := range b.items {
		if id == itemID {
			continue
		}
		if _, ok := versions[versionID]; ok {
			return true
		}
	}
	return false
}

// cloneTimePtr 返回结束时刻的独立副本，nil 原样返回。
// time.Time 是值类型，但账本持有的是 *time.Time，必须复制指针指向的值，
// 否则调用方修改自己的时间变量就会改写账本。
func cloneTimePtr(t *time.Time) *time.Time {
	if t == nil {
		return nil
	}
	cp := *t
	return &cp
}

// intervalsOverlap 判断半开区间 [s1,e1) 与 [s2,e2) 是否重叠，nil 终点表示持续有效。
// 时间比较按实际时刻进行，不同时区偏移不影响结果。
func intervalsOverlap(s1 time.Time, e1 *time.Time, s2 time.Time, e2 *time.Time) bool {
	if e1 != nil && !s2.Before(*e1) {
		return false
	}
	if e2 != nil && !s1.Before(*e2) {
		return false
	}
	return true
}

// versionView 构造账本版本的独立视图。
// 结束时刻必须复制后返回：登记结束与实际结束各自生成独立副本，
// 不同次查询之间也不共享指针，外部对任一返回结果的修改都不能改写账本边界。
func versionView(v *version) VersionView {
	return VersionView{
		ItemID:         v.itemID,
		VersionID:      v.versionID,
		UnitPrice:      v.unitPrice,
		Start:          v.start,
		End:            cloneTimePtr(v.end),
		Replaces:       v.replaces,
		SupersededBy:   v.supersededBy,
		EffectiveStart: v.start,
		EffectiveEnd:   cloneTimePtr(v.effEnd),
	}
}

// ItemVersions 返回费率项下各版本的登记信息与实际有效区间，按生效时刻排序。
func (b *Book) ItemVersions(itemID string) ([]VersionView, error) {
	b.mu.Lock()
	defer b.mu.Unlock()

	versions, ok := b.items[itemID]
	if !ok || len(versions) == 0 {
		return nil, ErrItemNotFound
	}
	views := make([]VersionView, 0, len(versions))
	for _, v := range versions {
		views = append(views, versionView(v))
	}
	sort.Slice(views, func(i, j int) bool {
		if !views[i].EffectiveStart.Equal(views[j].EffectiveStart) {
			return views[i].EffectiveStart.Before(views[j].EffectiveStart)
		}
		return views[i].VersionID < views[j].VersionID
	})
	return views, nil
}

// EffectiveVersionAt 返回指定费率项在 at 这一瞬间实际生效的单个版本。
//
// 选择依据是查询时账本已经登记的实际有效区间 [EffectiveStart, EffectiveEnd)：
// 开始时刻包含在内，结束时刻不包含在内，实际结束为 nil 表示持续有效。
// 旧版本被替代后，其实际有效区间止于交接时刻，从交接时刻起便不会再被选中，
// 即便它登记的结束时间仍在将来；替代它的新版本到期后也不会回退到旧版本。
// at 可以是过去或未来的任意瞬间，与账本时钟无关。
//
// 时间按实际时刻比较，同一瞬间的不同时区表示结论一致；
// 选择只在指定费率项内进行，其他费率项中同名的版本不参与。
//
// 费率项从未登记过版本时返回 ErrItemNotFound；费率项存在但该瞬间没有任何
// 生效版本（早于首版开始、落在两版之间的空档或全部已到期）时返回
// ErrNoEffectiveVersion，不会拿邻近版本补位。
//
// 该查询只读取版本信息，不受理报价、不占用请求标识，也不影响已保存的
// 受理结果。返回的 VersionView 是独立副本，修改其中的结束时间不会改变账本。
func (b *Book) EffectiveVersionAt(itemID string, at time.Time) (VersionView, error) {
	b.mu.Lock()
	defer b.mu.Unlock()

	versions, ok := b.items[itemID]
	if !ok || len(versions) == 0 {
		return VersionView{}, ErrItemNotFound
	}
	var found *version
	for _, v := range versions {
		if v.availabilityAt(at) != availabilityEffective {
			continue
		}
		// 同一费率项内各版本的实际有效区间互不重叠，至多一版命中。
		found = v
		break
	}
	if found == nil {
		return VersionView{}, ErrNoEffectiveVersion
	}
	return versionView(found), nil
}

// VersionsInRange 返回指定费率项在半开范围 [from, to) 内实际生效过的版本列表，
// 一次只查询一个费率项，调用方不必事先知道版本标识。
//
// 范围的开始时刻包含在内、结束时刻不包含；只有版本的实际有效区间
// [EffectiveStart, EffectiveEnd) 与该范围存在交集时才列出，仅在边界处相接
// （版本结束即范围开始，或版本开始即范围结束）不算命中。实际结束为 nil 的
// 持续有效版本按没有结束边界处理。
//
// 判断依据是查询时账本已经登记的实际有效区间：被替代的旧版按截短后的实际
// 结束参与判断，不会因为它登记的结束仍在范围内而被列入；替代它的新版到期后
// 旧版也不会恢复。范围内的空档不补入相邻版本。范围可以在过去或未来，
// 与账本时钟（WithClock）无关。时间按实际时刻比较，同一瞬间用不同时区
// 表示结论一致；其他费率项中同名的版本不参与。
//
// 返回的列表沿用 ItemVersions 的版本视图：版本标识、整数分单价、登记起止、
// 实际有效区间和替代关系（Replaces / SupersededBy）都保留账本中的原值，
// 不会把版本边界改成查询范围的边界。每个命中的版本只出现一次，按实际生效
// 起点从早到晚排列，起点相同时按版本标识的字符串顺序排列。
//
// 结束时刻不晚于开始时刻时返回 ErrInvalidRange（可用 errors.Is 判别），
// 不返回版本列表；范围合法但费率项从未登记过版本时返回 ErrItemNotFound；
// 费率项存在但范围内没有命中版本时返回空列表且不报错。
//
// 该查询只读取版本信息，不受理报价、不占用请求标识，也不影响已保存的
// 受理结果。返回的视图是独立副本，调用方修改其中的结束时间不会改变账本，
// 也不会影响后续查询与报价。
func (b *Book) VersionsInRange(itemID string, from, to time.Time) ([]VersionView, error) {
	if !to.After(from) {
		return nil, ErrInvalidRange
	}

	b.mu.Lock()
	defer b.mu.Unlock()

	versions, ok := b.items[itemID]
	if !ok || len(versions) == 0 {
		return nil, ErrItemNotFound
	}
	views := make([]VersionView, 0, len(versions))
	for _, v := range versions {
		// 实际有效区间 [v.start, v.effEnd) 与查询范围 [from, to) 有交集才命中；
		// 仅在边界处相接不算交集，effEnd 为 nil 按没有结束边界处理。
		if !intervalsOverlap(from, &to, v.start, v.effEnd) {
			continue
		}
		views = append(views, versionView(v))
	}
	sort.Slice(views, func(i, j int) bool {
		if !views[i].EffectiveStart.Equal(views[j].EffectiveStart) {
			return views[i].EffectiveStart.Before(views[j].EffectiveStart)
		}
		return views[i].VersionID < views[j].VersionID
	})
	return views, nil
}

// Quote 按首次受理时刻判断指定版本是否有效并给出报价。
// 非空请求标识的首次结果（无论确认还是拒绝）都会被保存；
// 相同标识且业务内容相同的重试返回首次结果，内容不同则返回 ErrRequestIDConflict。
func (b *Book) Quote(req QuoteRequest) (Outcome, error) {
	b.mu.Lock()
	defer b.mu.Unlock()

	if req.RequestID == "" {
		return Outcome{
			Request:    req,
			AcceptedAt: b.now(),
			Reason:     ReasonEmptyRequestID,
		}, nil
	}

	if prev, ok := b.requests[req.RequestID]; ok {
		same := prev.Request.ItemID == req.ItemID &&
			prev.Request.VersionID == req.VersionID &&
			prev.Request.Quantity == req.Quantity
		if !same {
			return Outcome{}, ErrRequestIDConflict
		}
		return prev, nil
	}

	out := Outcome{Request: req, AcceptedAt: b.now()}
	switch {
	case req.Quantity <= 0:
		out.Reason = ReasonInvalidQuantity
	default:
		v := b.items[req.ItemID][req.VersionID]
		// 可用性以首次受理时刻为准，与查询共用同一套实际有效期判断；
		// 只有版本有效后才判断总价是否溢出。
		var avail availability
		if v != nil {
			avail = v.availabilityAt(out.AcceptedAt)
		}
		switch {
		case v == nil:
			out.Reason = ReasonVersionNotFound
		case avail == availabilityNotYet:
			out.Reason = ReasonVersionNotYetEffective
		case avail == availabilityExpired:
			out.Reason = ReasonVersionExpired
		case v.unitPrice > 0 && req.Quantity > math.MaxInt64/v.unitPrice:
			out.Reason = ReasonTotalOverflow
		default:
			out.Confirmed = true
			out.UnitPrice = v.unitPrice
			out.Total = v.unitPrice * req.Quantity
		}
	}
	b.requests[req.RequestID] = out
	return out, nil
}

// Lookup 按请求标识查询保存的首次受理结果，未见过的标识返回 ErrRequestNotFound。
func (b *Book) Lookup(requestID string) (Outcome, error) {
	b.mu.Lock()
	defer b.mu.Unlock()

	out, ok := b.requests[requestID]
	if !ok {
		return Outcome{}, ErrRequestNotFound
	}
	return out, nil
}

// ItemOutcomes 返回当前账本中请求来源属于指定费率项的全部首次受理结果。
//
// 结果以已保存的首次请求来源（Outcome.Request.ItemID）为准，与该费率项是否
// 登记过版本无关：即使费率项从未登记过版本，合法数量的请求因 version_not_found
// 被拒绝的记录同样会被列出。其他费率项即使使用了同名版本也不会混入。
//
// 确认与拒绝都在结果中：不会因为引用的版本现在已经失效而筛掉记录，也不会按
// 当前单价重新计算已保存的金额；每条记录保留首次请求中的请求标识、费率项、
// 版本、数量，以及首次受理时刻、确认状态、单价、总价和拒绝原因。
// 相同请求标识的原样重试只返回首次结果，内容冲突不产生新记录，两者都不会
// 增加列表内容；空请求标识产生的拒绝不保存，因此不会出现在列表中。
//
// 列表按首次受理时刻从早到晚排列，时刻相同时按请求标识的字符串顺序排列。
// 非空费率项标识没有任何匹配记录时返回空列表且不报错；空费率项标识返回
// ErrEmptyItemIDQuery，调用方可用 errors.Is 明确识别这类输入错误。
//
// 该查询只读取账本已有的受理结果：不受理报价、不占用请求标识，
// Quote、Lookup、ItemVersions、EffectiveVersionAt 的既有规则都不受影响。
// 返回的列表及其中的每条记录都是独立副本，调用方修改后再做单笔查询、
// 原样重试或再次列表查询，仍得到账本保存的原始结果。
func (b *Book) ItemOutcomes(itemID string) ([]Outcome, error) {
	if itemID == "" {
		return nil, ErrEmptyItemIDQuery
	}

	b.mu.Lock()
	defer b.mu.Unlock()

	outcomes := make([]Outcome, 0)
	for _, out := range b.requests {
		if out.Request.ItemID == itemID {
			// Outcome 只含值类型字段（QuoteRequest 与 time.Time 均为值类型），
			// 直接复制即可得到与账本数据互不影响的独立记录。
			outcomes = append(outcomes, out)
		}
	}
	sort.Slice(outcomes, func(i, j int) bool {
		if !outcomes[i].AcceptedAt.Equal(outcomes[j].AcceptedAt) {
			return outcomes[i].AcceptedAt.Before(outcomes[j].AcceptedAt)
		}
		return outcomes[i].Request.RequestID < outcomes[j].Request.RequestID
	})
	return outcomes, nil
}

