1	package tariff
2	
3	import (
4		"errors"
5		"fmt"
6		"testing"
7		"time"
8	)
9	
10	// “开始、替代交接与到期全部落在同一秒内”的亚秒级有效期回归时间线。
11	// 所有时刻都以 2026-03-01 UTC 零点为起点按毫秒写死，结束时刻不含：
12	//
13	//	旧版 seat-v1：单价 150 分，第 100 毫秒起生效（含），登记结束为第 900 毫秒
14	//	新版 seat-v2：单价 180 分，第 500 毫秒起替代旧版（含），第 700 毫秒结束（不含）
15	//
16	// 两次登记的区间都是同一秒内的正长度区间：旧版实际有效区间被交接点截短为
17	// [100ms, 500ms)，新版实际有效区间为 [500ms, 700ms)，旧版登记结束 900ms 保持不变。
18	// 全部判断只按实际时刻进行（开始包含、结束不包含），时刻写死并注入固定时钟，
19	// 结论不依赖测试实际运行当天的日期或时间流逝。
20	var (
21		subSecBase   = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
22		subSecStart  = subSecBase.Add(100 * time.Millisecond) // 旧版生效起点（含）
23		subSecRegEnd = subSecBase.Add(900 * time.Millisecond) // 旧版登记结束（不含）
24		subSecHand   = subSecBase.Add(500 * time.Millisecond) // 交接点 / 新版起点（含）
25		subSecNewEnd = subSecBase.Add(700 * time.Millisecond) // 新版结束（不含）
26	)
27	
28	// newSubSecondBook 返回已按上述时间线登记 v1、v2 的账本与手动时钟。
29	// 两次登记都必须成功：亚秒级的正长度区间可以登记，交接点不能被提前到整秒。
30	func newSubSecondBook(t *testing.T) (*Book, func(time.Time)) {
31		t.Helper()
32		now, setNow := fixedClock(subSecStart)
33		b := NewBook(WithClock(now))
34	
35		oldEnd := subSecRegEnd
36		if err := b.RegisterVersion(RegisterRequest{
37			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
38			Start: subSecStart, End: &oldEnd,
39		}); err != nil {
40			t.Fatalf("register seat-v1: %v", err)
41		}
42		newEnd := subSecNewEnd
43		if err := b.RegisterVersion(RegisterRequest{
44			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
45			Start: subSecHand, End: &newEnd, Replaces: "seat-v1",
46		}); err != nil {
47			t.Fatalf("register seat-v2: %v", err)
48		}
49		return b, setNow
50	}
51	
52	// assertSubSecondTimesInSameSecond 是测试前提：整条时间线确实落在同一秒内，
53	// 且各边界彼此不同、毫秒偏移符合预期——否则本回归就没有测到亚秒级行为。
54	func assertSubSecondTimesInSameSecond(t *testing.T) {
55		t.Helper()
56		for name, ts := range map[string]time.Time{
57			"start": subSecStart, "regEnd": subSecRegEnd,
58			"hand": subSecHand, "newEnd": subSecNewEnd,
59		} {
60			if ts.Unix() != subSecBase.Unix() {
61				t.Fatalf("%s=%v 不在基准秒 %v 内", name, ts, subSecBase)
62			}
63		}
64		if !(subSecStart.Before(subSecHand) && subSecHand.Before(subSecNewEnd) &&
65			subSecNewEnd.Before(subSecRegEnd)) {
66			t.Fatalf("亚秒时间线顺序不成立: start=%v hand=%v newEnd=%v regEnd=%v",
67				subSecStart, subSecHand, subSecNewEnd, subSecRegEnd)
68		}
69	}
70	
71	// 亚秒级登记成功后，版本视图必须保留完整时刻的小数部分：
72	// 旧版登记结束仍是第 900 毫秒，实际结束被截短到第 500 毫秒；
73	// 新版保留自己的第 500 毫秒开始、第 700 毫秒结束和替代来源。
74	func TestSubSecondVersionViewPreservesFractions(t *testing.T) {
75		assertSubSecondTimesInSameSecond(t)
76		b, _ := newSubSecondBook(t)
77	
78		views, err := b.ItemVersions("seat")
79		if err != nil {
80			t.Fatal(err)
81		}
82		if len(views) != 2 {
83			t.Fatalf("应只有两个版本, got %d: %+v", len(views), views)
84		}
85		old, nv := views[0], views[1]
86		if old.VersionID != "seat-v1" || nv.VersionID != "seat-v2" {
87			t.Fatalf("版本顺序异常: %q, %q", old.VersionID, nv.VersionID)
88		}
89	
90		// 旧版：登记信息停留在 [100ms, 900ms)，实际有效区间被新版截短为 [100ms, 500ms)。
91		if old.UnitPrice != 150 {
92			t.Fatalf("旧版单价异常: %d", old.UnitPrice)
93		}
94		if !old.Start.Equal(subSecStart) || old.Start.Nanosecond() != 100_000_000 {
95			t.Fatalf("旧版开始应为第 100 毫秒且小数部分保留: %v", old.Start)
96		}
97		if old.End == nil || !old.End.Equal(subSecRegEnd) || old.End.Nanosecond() != 900_000_000 {
98			t.Fatalf("旧版登记结束应为第 900 毫秒且小数部分保留: %v", old.End)
99		}
100		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(subSecHand) ||
101			old.EffectiveEnd.Nanosecond() != 500_000_000 {
102			t.Fatalf("旧版实际结束应被截短到第 500 毫秒且小数部分保留: %v", old.EffectiveEnd)
103		}
104		if old.Replaces != "" || old.SupersededBy != "seat-v2" {
105			t.Fatalf("旧版替代关系异常: Replaces=%q SupersededBy=%q",
106				old.Replaces, old.SupersededBy)
107		}
108	
109		// 新版：[500ms, 700ms)，登记结束与实际结束一致，替代来源为旧版。
110		if nv.UnitPrice != 180 {
111			t.Fatalf("新版单价异常: %d", nv.UnitPrice)
112		}
113		if !nv.Start.Equal(subSecHand) || !nv.EffectiveStart.Equal(subSecHand) ||
114			nv.Start.Nanosecond() != 500_000_000 {
115			t.Fatalf("新版开始应为第 500 毫秒且小数部分保留: %+v", nv)
116		}
117		if nv.End == nil || !nv.End.Equal(subSecNewEnd) || nv.End.Nanosecond() != 700_000_000 ||
118			nv.EffectiveEnd == nil || !nv.EffectiveEnd.Equal(subSecNewEnd) ||
119			nv.EffectiveEnd.Nanosecond() != 700_000_000 {
120			t.Fatalf("新版结束应为第 700 毫秒且小数部分保留: 登记结束=%v 实际结束=%v",
121				nv.End, nv.EffectiveEnd)
122		}
123		if nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
124			t.Fatalf("新版替代关系异常: Replaces=%q SupersededBy=%q",
125				nv.Replaces, nv.SupersededBy)
126		}
127	
128		// 返回的结束时刻是独立副本：修改本次视图不能改写账本边界，
129		// 再次查询仍应看到完整的毫秒小数。
130		*views[0].End = subSecBase
131		*views[0].EffectiveEnd = subSecBase
132		*views[1].End = subSecBase
133		again, err := b.ItemVersions("seat")
134		if err != nil {
135			t.Fatal(err)
136		}
137		if again[0].End == nil || !again[0].End.Equal(subSecRegEnd) {
138			t.Fatalf("旧版登记结束被返回视图的外部修改改写: %v", again[0].End)
139		}
140		if again[0].EffectiveEnd == nil || !again[0].EffectiveEnd.Equal(subSecHand) {
141			t.Fatalf("旧版实际结束被返回视图的外部修改改写: %v", again[0].EffectiveEnd)
142		}
143		if again[1].End == nil || !again[1].End.Equal(subSecNewEnd) {
144			t.Fatalf("新版结束被返回视图的外部修改改写: %v", again[1].End)
145		}
146	}
147	
148	// 同一秒内的指定时刻查询：开始包含、结束不包含、交接点不能对齐到整秒。
149	// [100ms, 500ms) 选旧版；[500ms, 700ms) 选新版；第 700 毫秒起没有任何生效版本，
150	// 即便旧版登记的结束时刻第 900 毫秒还没到，也不能重新选中旧版。
151	func TestSubSecondEffectiveVersionAtBoundaries(t *testing.T) {
152		b, _ := newSubSecondBook(t)
153	
154		cases := []struct {
155			name      string
156			at        time.Time
157			versionID string
158			unitPrice int64
159		}{
160			{"旧版开始前一纳秒-无版本", subSecStart.Add(-time.Nanosecond), "", 0},
161			{"旧版开始本身-含", subSecStart, "seat-v1", 150},
162			{"旧版区间内", subSecBase.Add(300 * time.Millisecond), "seat-v1", 150},
163			{"交接点前一纳秒-仍是旧版", subSecHand.Add(-time.Nanosecond), "seat-v1", 150},
164			{"交接点本身-选新版", subSecHand, "seat-v2", 180},
165			{"新版区间内", subSecBase.Add(600 * time.Millisecond), "seat-v2", 180},
166			{"新版结束前一纳秒-仍是新版", subSecNewEnd.Add(-time.Nanosecond), "seat-v2", 180},
167			{"新版结束本身-无版本", subSecNewEnd, "", 0},
168			{"到期后早于旧版登记结束-不回退旧版", subSecBase.Add(800 * time.Millisecond), "", 0},
169			{"旧版登记结束前一纳秒-仍无版本", subSecRegEnd.Add(-time.Nanosecond), "", 0},
170			{"旧版登记结束本身-仍无版本", subSecRegEnd, "", 0},
171		}
172		for _, c := range cases {
173			t.Run(c.name, func(t *testing.T) {
174				view, err := b.EffectiveVersionAt("seat", c.at)
175				if c.versionID == "" {
176					if !errors.Is(err, ErrNoEffectiveVersion) {
177						t.Fatalf("时刻 %v 应返回 ErrNoEffectiveVersion, got %v (view=%+v)",
178							c.at, err, view)
179					}
180					return
181				}
182				if err != nil {
183					t.Fatalf("时刻 %v 应命中版本: %v", c.at, err)
184				}
185				if view.VersionID != c.versionID || view.UnitPrice != c.unitPrice {
186					t.Fatalf("时刻 %v 应选 %s（%d 分）, got %s（%d 分）",
187						c.at, c.versionID, c.unitPrice, view.VersionID, view.UnitPrice)
188				}
189			})
190		}
191	}
192	
193	// 在各边界时刻用新的非空请求标识、数量 4 引用指定版本报价：
194	// 有效旧版按 150 分确认 600 分，有效新版按 180 分确认 720 分；
195	// 交接前引用新版得到 version_not_yet_effective，交接点起引用旧版、
196	// 以及新版结束时引用新版，都得到 version_expired。拒绝也是正常受理
197	// （err 为空、单价总价为零），结果保留指定的费率项、版本、数量和
198	// 精确到纳秒的受理时刻，不自动改用另一版。
199	func TestSubSecondBoundaryQuotes(t *testing.T) {
200		b, setNow := newSubSecondBook(t)
201	
202		cases := []struct {
203			name      string
204			at        time.Time
205			versionID string
206			confirmed bool
207			unitPrice int64
208			total     int64
209			reason    RejectReason
210		}{
211			{"旧版开始本身-旧版确认", subSecStart, "seat-v1", true, 150, 600, ReasonNone},
212			{"交接点前一纳秒-旧版确认", subSecHand.Add(-time.Nanosecond), "seat-v1", true, 150, 600, ReasonNone},
213			{"交接点前一纳秒-新版尚未生效", subSecHand.Add(-time.Nanosecond), "seat-v2", false, 0, 0, ReasonVersionNotYetEffective},
214			{"交接点本身-旧版已失效", subSecHand, "seat-v1", false, 0, 0, ReasonVersionExpired},
215			{"交接点本身-新版确认", subSecHand, "seat-v2", true, 180, 720, ReasonNone},
216			{"新版结束前一纳秒-新版确认", subSecNewEnd.Add(-time.Nanosecond), "seat-v2", true, 180, 720, ReasonNone},
217			{"新版结束前一纳秒-旧版已失效", subSecNewEnd.Add(-time.Nanosecond), "seat-v1", false, 0, 0, ReasonVersionExpired},
218			{"新版结束本身-新版已失效", subSecNewEnd, "seat-v2", false, 0, 0, ReasonVersionExpired},
219			{"新版结束本身-旧版仍已失效", subSecNewEnd, "seat-v1", false, 0, 0, ReasonVersionExpired},
220			{"到期后早于旧版登记结束-旧版不复活", subSecBase.Add(800 * time.Millisecond), "seat-v1", false, 0, 0, ReasonVersionExpired},
221			{"到期后早于旧版登记结束-新版已失效", subSecBase.Add(800 * time.Millisecond), "seat-v2", false, 0, 0, ReasonVersionExpired},
222		}
223		for i, c := range cases {
224			t.Run(c.name, func(t *testing.T) {
225				setNow(c.at)
226				req := QuoteRequest{
227					// 每个时刻用全新的非空标识，避免命中幂等保留的首次结果。
228					RequestID: fmt.Sprintf("subsecond-%02d", i),
229					ItemID:    "seat",
230					VersionID: c.versionID,
231					Quantity:  4,
232				}
233				out, err := b.Quote(req)
234				if err != nil {
235					t.Fatalf("确认/拒绝都是正常受理，err 应为空, got %v", err)
236				}
237				if out.Confirmed != c.confirmed {
238					t.Fatalf("Confirmed=%v, want %v (%+v)", out.Confirmed, c.confirmed, out)
239				}
240				if out.UnitPrice != c.unitPrice || out.Total != c.total {
241					t.Fatalf("单价/总价=%d/%d, want %d/%d",
242						out.UnitPrice, out.Total, c.unitPrice, c.total)
243				}
244				if out.Reason != c.reason {
245					t.Fatalf("拒绝原因=%q, want %q", out.Reason, c.reason)
246				}
247				// 来源仍是调用方指定的版本与数量：拒绝不能自动改用另一版计算。
248				if out.Request != req {
249					t.Fatalf("结果未保留原请求的费率项/版本/数量: %+v vs %+v", out.Request, req)
250				}
251				// 受理时刻精确到纳秒：亚秒边界不能被截断到整秒。
252				if !out.AcceptedAt.Equal(c.at) || out.AcceptedAt.Unix() != c.at.Unix() ||
253					out.AcceptedAt.Nanosecond() != c.at.Nanosecond() {
254					t.Fatalf("受理时刻=%v, want 精确时刻 %v", out.AcceptedAt, c.at)
255				}
256	
257				// 首次结果（含拒绝）按标识保存，再次查询与受理时完全一致。
258				saved, err := b.Lookup(req.RequestID)
259				if err != nil {
260					t.Fatalf("首次受理结果应可按标识查询: %v", err)
261				}
262				if saved != out {
263					t.Fatalf("保存结果与受理结果不一致: %+v vs %+v", saved, out)
264				}
265			})
266		}
267	}
268	
269	// 同一秒内结束恰好等于开始或早于开始时，登记仍返回 ErrInvalidInterval，
270	// 不留版本、不占用版本标识，也不改写已有版本的时间与替代关系——
271	// 即使请求声明了替代旧版，截短也不能发生。
272	func TestSubSecondInvalidIntervalRejectedWithoutTrace(t *testing.T) {
273		cases := []struct {
274			name      string
275			versionID string
276			start     time.Time
277			end       time.Time
278			replaces  string
279		}{
280			{
281				"结束恰好等于开始-不提前到整秒",
282				"seat-v3-eq",
283				subSecBase.Add(150 * time.Millisecond),
284				subSecBase.Add(150 * time.Millisecond),
285				"seat-v1",
286			},
287			{
288				"结束早于开始-同在一秒内",
289				"seat-v3-before",
290				subSecBase.Add(150 * time.Millisecond),
291				subSecBase.Add(140 * time.Millisecond),
292				"seat-v1",
293			},
294		}
295		for _, c := range cases {
296			t.Run(c.name, func(t *testing.T) {
297				b, _ := newSubSecondBook(t)
298	
299				err := b.RegisterVersion(RegisterRequest{
300					ItemID: "seat", VersionID: c.versionID, UnitPrice: 200,
301					Start: c.start, End: &c.end, Replaces: c.replaces,
302				})
303				if !errors.Is(err, ErrInvalidInterval) {
304					t.Fatalf("应返回 ErrInvalidInterval, got %v", err)
305				}
306	
307				views, err := b.ItemVersions("seat")
308				if err != nil {
309					t.Fatal(err)
310				}
311				if len(views) != 2 {
312					t.Fatalf("失败登记不应留下版本，应仍只有 2 个, got %d: %+v",
313						len(views), views)
314				}
315				old, nv := views[0], views[1]
316				if old.VersionID != "seat-v1" || nv.VersionID != "seat-v2" {
317					t.Fatalf("失败登记后版本集合异常: %q, %q", old.VersionID, nv.VersionID)
318				}
319	
320				// 旧版的登记结束、截短后的实际结束与替代关系都保持不变。
321				if old.End == nil || !old.End.Equal(subSecRegEnd) ||
322					old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(subSecHand) {
323					t.Fatalf("旧版时间被失败登记改写: 登记结束=%v 实际结束=%v",
324						old.End, old.EffectiveEnd)
325				}
326				if old.SupersededBy != "seat-v2" {
327					t.Fatalf("旧版替代关系被失败登记改写: SupersededBy=%q", old.SupersededBy)
328				}
329				// 新版的开始、结束与替代来源保持不变。
330				if !nv.Start.Equal(subSecHand) || nv.End == nil || !nv.End.Equal(subSecNewEnd) ||
331					nv.Replaces != "seat-v1" {
332					t.Fatalf("新版信息被失败登记改写: %+v", nv)
333				}
334	
335				// 失败不占用版本标识：同一标识用于一次落在 v1 剩余实际区间
336				// [100ms, 500ms) 内、结束与交接点相接（不含）的合法登记，
337				// 必须成功——端点相接不能与新版 [500ms, 700ms) 误判重叠。
338				goodEnd := subSecHand
339				if err := b.RegisterVersion(RegisterRequest{
340					ItemID: "seat", VersionID: c.versionID, UnitPrice: 200,
341					Start: c.start, End: &goodEnd, Replaces: "seat-v1",
342				}); err != nil {
343					t.Fatalf("失败登记不应占用版本标识，合法登记应成功, got %v", err)
344				}
345			})
346		}
347	}
348

