144	// 3 月 20 日至 3 月 25 日只得到 v3。范围只覆盖任一交接点前后一纳秒时，
145	// 应列出在该范围内先后生效的相邻两版，边界附近的时间精度不能丢失。
146	func TestVersionsInRangeSecondTruncationHandoffBoundaries(t *testing.T) {
147		b := newTwiceTruncatedRangeBook(t)
148	
