	if err := b.RegisterVersion(RegisterRequest{
		// 标识刻意取字符串顺序更靠前的 "a..."，但生效更晚。
		ItemID: "fare", VersionID: "a-fare-new", UnitPrice: 180,
		Start: subSecHand, End: &newEnd, Replaces: "z-fare-old",
	}); err != nil {
		t.Fatalf("register a-fare-new: %v", err)
	}

